type S5U2WordText = {
  ko: string;
  uz: string;
  en: string;
  ru: string;
};

type S5U2WordInput = {
  code: string;
  korean: string;
  senseKey: string;
  partOfSpeech: WordPartOfSpeech;
  meaning: S5U2WordText;
  example: string;
  exampleTranslations: S5U2WordText;
  romanization: string;
  emoji: string;
  tags: string[];
  difficulty?: number;
  usageNote?: S5U2WordText;
  isCore?: boolean;
};

const S5U2T = (
  ko: string,
  uz: string,
  en: string,
  ru: string,
): S5U2WordText => ({
  ko,
  uz,
  en,
  ru,
});

const makeS5U2Word = ({
  code,
  korean,
  senseKey,
  partOfSpeech,
  meaning,
  example,
  exampleTranslations,
  romanization,
  emoji,
  tags,
  difficulty = 4,
  usageNote,
  isCore = false,
}: S5U2WordInput): WordSeedEntry => ({
  code,
  korean,
  senseKey,
  partOfSpeech,
  meaning,
  examples: [
    {
      korean: example,
      translations: exampleTranslations,
    },
  ],
  pronunciation: {
    hangul: korean,
    romanization,
    ttsText: korean,
  },
  media: {
    emoji,
    imageUrl: '',
    imageAlt: {
      ko: `${korean}의 의미를 나타내는 이미지`,
      uz: `${korean} ma’nosini ifodalovchi rasm`,
      en: `an image representing ${meaning.en}`,
      ru: `изображение со значением «${meaning.ru}»`,
    },
  },
  tags: ['s5-unit2', ...tags],
  difficulty,
  usageNote:
    usageNote ??
    S5U2T(
      '서울대 한국어 3A 2과에서 학습하는 어휘예요.',
      'Seul milliy universiteti koreys tili 3A 2-darsida o‘rganiladigan so‘z yoki ifoda.',
      'A vocabulary item taught in Seoul National University Korean 3A Unit 2.',
      'Слово или выражение из урока 2 учебника Seoul National University Korean 3A.',
    ),
  isCore,
});

